use kimo_core::{color::{apply3,catalog3},effects::{Frame,Params},keyframe::Prop};
#[test]fn every_color_effect_extreme_render_is_finite_or_error(){
    let skip:[&str;0]=[];let mut calls=0;
    for (kind,_,ps) in catalog3(){if skip.contains(kind){continue}for v in [-1e8,0.,1e8]{let mut pr=Params::new();for(k,_,_)in *ps{pr.insert(k.to_string(),Prop::new(v));}let mut f=Frame{w:16,h:16,d:vec![0.3;16*16*4]};let r=apply3(kind,&pr,&mut f,0.,0);if r.is_ok(){assert!(f.d.iter().all(|x|x.is_finite()),"{kind} returned nonfinite output")}calls+=1;}}
    assert!(calls>=54);
}
#[test]fn malformed_render_times_fail(){use kimo_core::{model::Project,render};let p=Project::default();for t in [f64::NAN,f64::INFINITY,f64::NEG_INFINITY]{let mut cache=render::Cache::new();assert!(render::prepare_at(&p,&mut cache,Some(t)).is_err());assert!(render::render_frame(&p,t,&cache).is_err());}let mut cache=render::Cache::new();assert!(render::prepare_range(&p,&mut cache,1.,0.).is_err());assert!(render::prepare(&p,&mut cache).is_ok());}
#[test]fn direct_managed_effects_reject_bad_frame_before_write(){use kimo_core::color::{managed,linear,adaptation,shoulder,gamut_ray};let fns:[fn(&Params,&mut Frame,f64)->Result<(),String>;5]=[managed::apply,linear::apply,adaptation::apply,shoulder::apply,gamut_ray::apply];for apply in fns{for (w,h,d) in [(1,1,vec![0.;3]),(usize::MAX,2,vec![]),(1,1,vec![0.1,0.2,0.3,1.01]),(1,1,vec![0.1,f32::INFINITY,0.3,1.])]{let mut f=Frame{w,h,d};let original=f.d.clone();assert!(apply(&Params::new(),&mut f,0.).is_err());assert_eq!(f.d,original);}}}
#[test]fn late_invalid_sample_is_rejected_before_write(){use kimo_core::color::{managed,linear,adaptation,shoulder,gamut_ray,curves,cdl};let effects:[fn(&Params,&mut Frame,f64)->Result<(),String>;7]=[managed::apply,linear::apply,adaptation::apply,shoulder::apply,gamut_ray::apply,curves::apply,cdl::apply];for apply in effects{for bad in [f32::NAN,f32::INFINITY,-0.1,1.1]{let mut f=Frame{w:65537,h:1,d:vec![0.25;65537*4]};let n=f.d.len();f.d[n-1]=bad;let before:Vec<_>=f.d.iter().map(|v|v.to_bits()).collect();assert!(apply(&Params::new(),&mut f,0.).is_err());assert_eq!(f.d.iter().map(|v|v.to_bits()).collect::<Vec<_>>(),before);}}}
